using System;
using UnityEngine;
using TMPro;
namespace Maze {
 public static class BlueUi {
  public const float Width=1672,Height=941;
  public static readonly Color Navy=new Color32(7,17,81,255),Muted=new Color32(82,116,168,255),Blue=new Color32(7,136,255,255),PanelColor=new Color32(232,247,255,255),Gold=new Color32(255,207,38,255),Green=new Color32(8,169,48,255),Red=new Color32(255,75,64,255),White=Color.white;
  public static Sprite Art(string id)=>Resources.Load<Sprite>("BlueUI/Art/"+id);
  public static RectTransform Rect(Transform p,string n,float x,float y,float w,float h){var r=Holo.Rect(p,n);r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
  public static RectTransform Frame(Transform p,string n){var safe=Holo.SafeRoot(p);var f=Holo.Rect(safe,n,Vector2.one*.5f,Vector2.zero,new Vector2(Width,Height));f.gameObject.AddComponent<BlueFrameFit>().Init(safe);return f;}
  public static UnityEngine.UI.Image Image(Transform p,string n,string art,float x,float y,float w,float h,bool sliced=false)=>Image(p,n,Art(art),x,y,w,h,sliced);
  public static UnityEngine.UI.Image Image(Transform p,string n,Sprite art,float x,float y,float w,float h,bool sliced=false){var i=Holo.Img(Rect(p,n,x,y,w,h),art,Color.white,sliced);i.raycastTarget=false;i.preserveAspect=!sliced;return i;}
  public static UnityEngine.UI.Image Panel(Transform p,string n,float x,float y,float w,float h,bool soft=false,bool border=false)=>Image(p,n,border?"panel_border":soft?"panel_soft":"panel_main",x,y,w,h,true);
  public static TMP_Text Text(Transform p,string n,string value,float x,float y,float w,float h,float size=36,Color? color=null,bool body=false){var t=Rect(p,n,x,y,w,h).gameObject.AddComponent<TextMeshProUGUI>();t.font=Resources.Load<TMP_FontAsset>("BlueUI/Fonts/"+(body?"Body":"Display"));if(t.font==null)throw new InvalidOperationException("Blue UI font is not imported: "+n);t.fontSize=t.fontSizeMax=size;t.fontSizeMin=Mathf.Max(16,size-8);t.enableAutoSizing=true;t.text=value;t.color=color??Navy;t.alignment=TextAlignmentOptions.MidlineLeft;t.textWrappingMode=TextWrappingModes.Normal;t.overflowMode=TextOverflowModes.Truncate;t.raycastTarget=false;t.margin=Vector4.zero;return t;}
  public static UnityEngine.UI.Button Button(Transform p,string n,string label,float x,float y,float w,float h,Action action,bool primary=false,string icon=null,float fontSize=42){float pw=Mathf.Max(124,w),ph=Mathf.Max(124,h),dx=(pw-w)*.5f,dy=(ph-h)*.5f;var r=Rect(p,n,x-dx,y-dy,pw,ph);var touch=Holo.Img(Holo.Fill(r,"TouchTarget"),Holo.WhiteSprite,Color.clear,false,true);var face=Image(r,"Surface",primary?(h>=110?"button_yellow_large_blank":"button_yellow_blank"):(h>=110?"button_blue_large_blank":"button_blue_blank"),dx,dy,w,h,true);var b=r.gameObject.AddComponent<UnityEngine.UI.Button>();b.targetGraphic=face;b.navigation=new UnityEngine.UI.Navigation{mode=UnityEngine.UI.Navigation.Mode.None};var c=b.colors;c.normalColor=c.highlightedColor=Color.white;c.pressedColor=new Color(.78f,.85f,.95f);c.disabledColor=new Color(.55f,.62f,.73f,.7f);c.fadeDuration=.06f;b.colors=c;b.gameObject.AddComponent<BlueButtonMotion>();b.onClick.AddListener(()=>action?.Invoke());float left=icon==null?18:Mathf.Min(100,h*.65f);if(icon!=null)Image(r,"Icon",icon,dx+(string.IsNullOrEmpty(label)?(w-h*.6f)*.5f:22),dy+h*.2f,h*.6f,h*.6f);var tx=Text(r,"Label",label,dx+left,dy+8,w-left-18,h-16,fontSize,primary?Navy:White);tx.alignment=TextAlignmentOptions.Center;if(!primary){tx.outlineColor=new Color32(20,94,185,255);tx.outlineWidth=.14f;}return b;}
  public static UnityEngine.UI.Image Scrim(Transform p,string n,Color color){var im=Holo.Img(Holo.Fill(p,n),Holo.WhiteSprite,color,false,true);im.gameObject.AddComponent<BlueScreenFill>();return im;}
  public static void Background(Transform p,string art="scene_equipment",float dim=0){var raw=Holo.Raw(Holo.Fill(p,"BlueEnvironment"),Resources.Load<Texture2D>("BlueUI/Art/"+art),Color.white);raw.raycastTarget=true;if(raw.texture!=null)raw.gameObject.AddComponent<CoverUv>().aspect=(float)raw.texture.width/raw.texture.height;if(dim>0){var im=Holo.Img(Holo.Fill(p,"BlueEnvironmentShade"),Holo.WhiteSprite,new Color(Navy.r,Navy.g,Navy.b,dim));im.raycastTarget=false;}}
  public static UnityEngine.UI.Image Avatar(Transform p,string n,float x,float y,float w,float h,string pose="standing")=>Image(p,n,"hero_"+pose,x,y,w,h);
  public static BlueWallet Wallet(Transform p,float x=1110,float y=24){var root=Rect(p,"Wallet",x,y,526,78);var w=root.gameObject.AddComponent<BlueWallet>();w.Init();return w;}
 }
 [DefaultExecutionOrder(10000)] public sealed class BlueScreenFill:MonoBehaviour {RectTransform r;Canvas canvas;readonly Vector3[] corners=new Vector3[4];void OnEnable()=>Fit();void LateUpdate()=>Fit();void Fit(){if(r==null)r=(RectTransform)transform;if(canvas==null)canvas=GetComponentInParent<Canvas>()?.rootCanvas;if(canvas==null||r.parent is not RectTransform parent)return;var full=(RectTransform)canvas.transform;if(full.rect.width<=0||full.rect.height<=0)return;full.GetWorldCorners(corners);var a=parent.InverseTransformPoint(corners[0]);var b=parent.InverseTransformPoint(corners[2]);r.anchorMin=r.anchorMax=r.pivot=Vector2.zero;r.localScale=Vector3.one;r.localRotation=Quaternion.identity;r.sizeDelta=new Vector2(b.x-a.x+2,b.y-a.y+2);r.localPosition=new Vector3(a.x-1,a.y-1,0);}}
 public sealed class BlueFrameFit:MonoBehaviour {RectTransform safe,frame;Vector2 last;public void Init(RectTransform s){safe=s;frame=(RectTransform)transform;Fit();}void LateUpdate()=>Fit();void Fit(){if(safe==null)return;var size=safe.rect.size;if(size==last||size.x<=0||size.y<=0)return;last=size;frame.localScale=Vector3.one*Mathf.Min(size.x/BlueUi.Width,size.y/BlueUi.Height);}}
 public sealed class BlueWallet:MonoBehaviour {TMP_Text[] labels=new TMP_Text[3];int a=-1,b=-1,c=-1;public void Init(){string[] ids={"currency_coin","currency_parts","currency_alloy"};for(int k=0;k<3;k++){var plate=BlueUi.Image(transform,"CurrencyPlate"+k,"wallet_pill",k*176+24,8,142,51,true);BlueUi.Image(transform,ids[k],ids[k],k*176,0,66,68);labels[k]=BlueUi.Text(transform,"Amount"+k,"",k*176+60,8,103,50,32,Color.white);labels[k].alignment=TextAlignmentOptions.Center;labels[k].fontSizeMin=18;}Refresh();}public void Refresh(){if(labels[0]==null)return;a=Progress.D.credits;b=Progress.D.parts;c=Progress.D.alloy;labels[0].text=a.ToString("N0");labels[1].text=b.ToString("N0");labels[2].text=c.ToString("N0");}void LateUpdate(){if(a!=Progress.D.credits||b!=Progress.D.parts||c!=Progress.D.alloy)Refresh();}}
}
